-- ===== supabase/migrations/20260920_feed_leveling.sql =====
-- Feed leveling: anonymized social-proof aggregates + link/created indexes.
-- Additive only. Safe to re-run. Does not drop or rewrite existing tables.
-- Depends on: public.contests, tracking.contest_entries (bootstrap / prior migrations).

-- ---------------------------------------------------------------------------
-- Indexes for dead-link hygiene + New rail + entry aggregates
-- ---------------------------------------------------------------------------
create index if not exists idx_contests_link_status
  on public.contests (link_status)
  where link_status is not null;

create index if not exists idx_contests_created_at
  on public.contests (created_at desc);

create index if not exists idx_contest_entries_entered_at
  on tracking.contest_entries (entered_at desc);

create index if not exists idx_contest_entries_contest_day
  on tracking.contest_entries (contest_id, entered_at);

-- Optional denormalized daily count on Hive Mind (clients may also use RPC live).
alter table public.contests
  add column if not exists entries_today int not null default 0;

comment on column public.contests.entries_today is
  'Optional denormalized anonymized entry count for the Toronto calendar day; refresh via RPC/cron.';

comment on column public.profiles.settings is
  'jsonb: geoFilter, quebecSafe, ageConfirmed, notifications, welcome_granted, …';

-- ---------------------------------------------------------------------------
-- Anonymized daily entry counts (no usernames / user_ids returned)
-- ---------------------------------------------------------------------------
create or replace function public.contest_entries_today(p_contest_id text default null)
returns table (contest_id text, entries_today bigint)
language sql
security definer
set search_path = public, tracking
stable
as $$
  select e.contest_id, count(*)::bigint as entries_today
  from tracking.contest_entries e
  where e.entered_at >= (date_trunc('day', timezone('America/Toronto', now()))
                         at time zone 'America/Toronto')
    and e.status in ('entered', 'submitted', 'won')
    and (p_contest_id is null or e.contest_id = p_contest_id)
  group by e.contest_id;
$$;

comment on function public.contest_entries_today(text) is
  'Privacy-safe aggregate: contest_id + count of entries today (Toronto day). No user identity.';

grant execute on function public.contest_entries_today(text) to anon, authenticated;

-- Global Hive Mind total for today (single scalar for home social proof).
create or replace function public.hive_entries_today()
returns bigint
language sql
security definer
set search_path = public, tracking
stable
as $$
  select count(*)::bigint
  from tracking.contest_entries e
  where e.entered_at >= (date_trunc('day', timezone('America/Toronto', now()))
                         at time zone 'America/Toronto')
    and e.status in ('entered', 'submitted', 'won');
$$;

comment on function public.hive_entries_today() is
  'Anonymized count of all contest entries marked today (Toronto day). No usernames.';

grant execute on function public.hive_entries_today() to anon, authenticated;

-- ===== supabase/migrations/20260920_pro_iap_earn.sql =====
-- =============================================================================
-- LoonieWins — Pro IAP / AdGem postbacks / streak protection (ADDITIVE)
-- Requires freemium migration (20260320000000_freemium_monetization.sql) first.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Profiles: streak grace + comeback tracking + IAP entitlement mirror
-- ---------------------------------------------------------------------------
alter table public.profiles
  add column if not exists streak_grace_available boolean default true,
  add column if not exists last_comeback_bonus_at date,
  add column if not exists iap_product_id text,
  add column if not exists iap_expires_at timestamptz;

comment on column public.profiles.streak_grace_available is
  'One free miss day; consumed when last_streak_at is exactly 2 UTC days ago.';
comment on column public.profiles.last_comeback_bonus_at is
  'UTC date of last comeback bonus after a broken streak.';

-- ---------------------------------------------------------------------------
-- Expand transaction types
-- ---------------------------------------------------------------------------
do $$
begin
  alter table tracking.transactions drop constraint if exists transactions_type_check;
exception when undefined_table then null;
end $$;

alter table tracking.transactions
  drop constraint if exists transactions_type_check;

alter table tracking.transactions
  add constraint transactions_type_check
  check (type in (
    'survey', 'purchase', 'referral', 'pro_pass', 'bonus', 'entry_spend',
    'offerwall', 'referral_click', 'referral_signup', 'streak_bonus',
    'comeback_bonus', 'iap'
  ));

-- ---------------------------------------------------------------------------
-- Idempotent offerwall completions (AdGem postbacks)
-- ---------------------------------------------------------------------------
create table if not exists tracking.offerwall_completions (
  id uuid primary key default gen_random_uuid(),
  provider text not null default 'adgem',
  external_id text not null,
  player_id uuid not null references auth.users (id) on delete cascade,
  amount_points int not null check (amount_points >= 0),
  payout_usd numeric,
  campaign_id text,
  raw jsonb default '{}'::jsonb,
  created_at timestamptz default now(),
  unique (provider, external_id)
);

create index if not exists idx_offerwall_completions_player
  on tracking.offerwall_completions (player_id, created_at desc);

alter table tracking.offerwall_completions enable row level security;

drop policy if exists "Users read own offerwall completions" on tracking.offerwall_completions;
create policy "Users read own offerwall completions"
  on tracking.offerwall_completions for select
  using (auth.uid() = player_id);

-- No insert/update for authenticated — only service_role via Edge Function
grant select on tracking.offerwall_completions to authenticated;
grant all on tracking.offerwall_completions to service_role;

-- ---------------------------------------------------------------------------
-- RPC: credit_offerwall_completion — security definer; called with service role
-- ---------------------------------------------------------------------------
create or replace function public.credit_offerwall_completion(
  p_provider text,
  p_external_id text,
  p_player_id uuid,
  p_amount_points int,
  p_payout_usd numeric default null,
  p_campaign_id text default null,
  p_raw jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, tracking
as $$
declare
  pts int := greatest(coalesce(p_amount_points, 0), 0);
begin
  if p_provider is null or length(trim(p_provider)) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'missing_provider');
  end if;
  if p_external_id is null or length(trim(p_external_id)) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'missing_external_id');
  end if;
  if p_player_id is null then
    return jsonb_build_object('ok', false, 'reason', 'missing_player_id');
  end if;
  if pts <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'bad_amount');
  end if;

  begin
    insert into tracking.offerwall_completions (
      provider, external_id, player_id, amount_points, payout_usd, campaign_id, raw
    ) values (
      lower(trim(p_provider)), trim(p_external_id), p_player_id, pts,
      p_payout_usd, p_campaign_id, coalesce(p_raw, '{}'::jsonb)
    );
  exception when unique_violation then
    return jsonb_build_object('ok', true, 'duplicate', true, 'points_awarded', 0);
  end;

  update public.profiles
    set points_balance = coalesce(points_balance, 0) + pts,
        updated_at = now()
    where id = p_player_id;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'player_not_found');
  end if;

  insert into tracking.transactions (user_id, amount, type, description, metadata)
  values (
    p_player_id,
    pts,
    'offerwall',
    'Offerwall credit (' || lower(trim(p_provider)) || ')',
    jsonb_build_object(
      'provider', lower(trim(p_provider)),
      'external_id', trim(p_external_id),
      'campaign_id', p_campaign_id,
      'payout_usd', p_payout_usd
    )
  );

  return jsonb_build_object('ok', true, 'duplicate', false, 'points_awarded', pts);
end;
$$;

revoke all on function public.credit_offerwall_completion(text, text, uuid, int, numeric, text, jsonb) from public;
-- Invoked by Edge Function with service role (bypasses grant) or explicitly:
grant execute on function public.credit_offerwall_completion(text, text, uuid, int, numeric, text, jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- RPC: apply_iap_entitlement — mirror store entitlement onto profile
-- ---------------------------------------------------------------------------
create or replace function public.apply_iap_entitlement(
  p_user_id uuid,
  p_tier text,
  p_product_id text default null,
  p_expires_at timestamptz default null,
  p_active boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = public, tracking
as $$
declare
  tier text := lower(coalesce(p_tier, 'free'));
begin
  if p_user_id is null then
    return jsonb_build_object('ok', false, 'reason', 'missing_user');
  end if;

  if not p_active or tier = 'free' or tier not in ('weekly', 'monthly') then
    update public.profiles
      set subscription_tier = 'free',
          is_premium = false,
          iap_product_id = null,
          iap_expires_at = null,
          updated_at = now()
      where id = p_user_id;
    return jsonb_build_object('ok', true, 'active', false, 'tier', 'free');
  end if;

  update public.profiles
    set subscription_tier = tier,
        is_premium = true,
        iap_product_id = p_product_id,
        iap_expires_at = p_expires_at,
        feature_flags = coalesce(feature_flags, '{}'::jsonb) ||
          jsonb_build_object(
            'unlimited_entries', true,
            'unlimited_smart_fills', true,
            'priority_sources', true
          ),
        updated_at = now()
    where id = p_user_id;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'profile_missing');
  end if;

  insert into tracking.transactions (user_id, amount, type, description, metadata)
  values (
    p_user_id,
    0,
    'iap',
    'Pro entitlement synced',
    jsonb_build_object('tier', tier, 'product_id', p_product_id, 'expires_at', p_expires_at)
  );

  return jsonb_build_object('ok', true, 'active', true, 'tier', tier);
end;
$$;

revoke all on function public.apply_iap_entitlement(uuid, text, text, timestamptz, boolean) from public;
grant execute on function public.apply_iap_entitlement(uuid, text, text, timestamptz, boolean) to service_role;

-- ---------------------------------------------------------------------------
-- Replace award_entry_progress with grace miss + comeback bonus
-- ---------------------------------------------------------------------------
create or replace function public.award_entry_progress(
  p_contest_id text,
  p_status text default 'entered'
)
returns jsonb
language plpgsql
security definer
set search_path = public, tracking
as $$
declare
  uid uuid := auth.uid();
  row public.profiles;
  xp_gain int := 0;
  new_xp int;
  new_streak int;
  today date := (timezone('utc', now()))::date;
  yesterday date := (timezone('utc', now()))::date - 1;
  grace_day date := (timezone('utc', now()))::date - 2;
  existing tracking.contest_entries;
  first_enter boolean := false;
  first_submit boolean := false;
  used_grace boolean := false;
  comeback_pts int := 0;
  comeback_xp int := 0;
  prev_streak int;
  grace_left boolean;
begin
  if uid is null then
    return jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  end if;
  if p_contest_id is null or length(trim(p_contest_id)) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'missing_contest_id');
  end if;
  if p_status not in ('entered', 'submitted', 'won', 'lost', 'expired') then
    return jsonb_build_object('ok', false, 'reason', 'bad_status');
  end if;

  select * into existing
    from tracking.contest_entries
    where user_id = uid and contest_id = p_contest_id;

  if not found then
    first_enter := true;
    if p_status = 'submitted' then
      first_submit := true;
    end if;
  else
    if existing.status is distinct from 'submitted'
       and existing.status is distinct from 'won'
       and p_status in ('submitted', 'won') then
      first_submit := true;
    end if;
  end if;

  if first_enter then
    xp_gain := xp_gain + 15;
  end if;
  if first_submit then
    xp_gain := xp_gain + 35;
  end if;

  select * into row from public.profiles where id = uid for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'profile_missing');
  end if;

  new_xp := coalesce(row.xp, 0) + xp_gain;
  new_streak := coalesce(row.streak, 0);
  prev_streak := coalesce(row.streak, 0);
  grace_left := coalesce(row.streak_grace_available, true);

  if xp_gain > 0 then
    if row.last_streak_at is null then
      new_streak := 1;
      grace_left := true;
    elsif row.last_streak_at = today then
      new_streak := greatest(coalesce(row.streak, 0), 1);
    elsif row.last_streak_at = yesterday then
      new_streak := coalesce(row.streak, 0) + 1;
    elsif row.last_streak_at = grace_day and grace_left then
      -- One-day grace miss: keep streak continuity
      new_streak := coalesce(row.streak, 0) + 1;
      grace_left := false;
      used_grace := true;
    else
      -- Broken streak — reset + optional comeback bonus
      new_streak := 1;
      grace_left := true;
      if prev_streak >= 3
         and (row.last_comeback_bonus_at is null or row.last_comeback_bonus_at < today) then
        comeback_xp := 50;
        comeback_pts := 100;
        new_xp := new_xp + comeback_xp;
      end if;
    end if;

    update public.profiles
      set xp = new_xp,
          level = public.level_for_xp(new_xp),
          streak = new_streak,
          last_streak_at = today,
          streak_grace_available = grace_left,
          last_comeback_bonus_at = case
            when comeback_pts > 0 then today
            else row.last_comeback_bonus_at
          end,
          points_balance = case
            when comeback_pts > 0 then coalesce(points_balance, 0) + comeback_pts
            else points_balance
          end,
          updated_at = now()
      where id = uid
      returning * into row;

    if comeback_pts > 0 then
      insert into tracking.transactions (user_id, amount, type, description, metadata)
      values (
        uid,
        comeback_pts,
        'comeback_bonus',
        'Comeback bonus after returning to your streak',
        jsonb_build_object('prev_streak', prev_streak, 'xp_bonus', comeback_xp)
      );
    end if;

    if used_grace then
      insert into tracking.transactions (user_id, amount, type, description, metadata)
      values (
        uid,
        0,
        'streak_bonus',
        'Streak protection used (grace miss)',
        jsonb_build_object('streak', new_streak)
      );
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'xp_gained', xp_gain + comeback_xp,
    'xp', row.xp,
    'level', row.level,
    'streak', row.streak,
    'first_enter', first_enter,
    'first_submit', first_submit,
    'used_grace', used_grace,
    'comeback_points', comeback_pts,
    'comeback_xp', comeback_xp,
    'streak_grace_available', grace_left
  );
end;
$$;

revoke all on function public.award_entry_progress(text, text) from public;
grant execute on function public.award_entry_progress(text, text) to authenticated;

-- ===== supabase/migrations/20260920_push_notifications.sql =====
-- =============================================================================
-- LoonieWins — ADDITIVE migration: push tokens + alert dedupe
-- =============================================================================
-- Safe to run on a project that already has the full bootstrap (profiles,
-- contests, tracking.*, giveaways.*). Does NOT drop or rewrite existing tables.
--
-- Run in: Supabase Dashboard → SQL Editor → New query → Run
-- Then: deploy Edge Function `send-push-alerts` and schedule it (see docs).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- public.push_tokens — Expo / device push token registration
-- ---------------------------------------------------------------------------
create table if not exists public.push_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  expo_push_token text not null,
  platform text not null default 'unknown'
    check (platform in ('ios', 'android', 'web', 'unknown')),
  device_id text,
  app_version text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, expo_push_token)
);

create index if not exists idx_push_tokens_user
  on public.push_tokens (user_id);

create index if not exists idx_push_tokens_token
  on public.push_tokens (expo_push_token);

drop trigger if exists push_tokens_updated_at on public.push_tokens;
create trigger push_tokens_updated_at
  before update on public.push_tokens
  for each row execute function public.update_updated_at();

alter table public.push_tokens enable row level security;

drop policy if exists "Users read own push tokens" on public.push_tokens;
create policy "Users read own push tokens"
  on public.push_tokens for select
  using (auth.uid() = user_id);

drop policy if exists "Users insert own push tokens" on public.push_tokens;
create policy "Users insert own push tokens"
  on public.push_tokens for insert
  with check (auth.uid() = user_id);

drop policy if exists "Users update own push tokens" on public.push_tokens;
create policy "Users update own push tokens"
  on public.push_tokens for update
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

drop policy if exists "Users delete own push tokens" on public.push_tokens;
create policy "Users delete own push tokens"
  on public.push_tokens for delete
  using (auth.uid() = user_id);

grant select, insert, update, delete on public.push_tokens to authenticated;
grant all on public.push_tokens to service_role;

comment on table public.push_tokens is
  'Expo push tokens per signed-in user/device. Prefs live in profiles.settings.notifications.';

-- ---------------------------------------------------------------------------
-- public.push_alert_log — prevent duplicate new/ending alerts per contest
-- ---------------------------------------------------------------------------
create table if not exists public.push_alert_log (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  contest_id text not null,
  alert_type text not null
    check (alert_type in ('new_contest', 'ending_tonight')),
  sent_at timestamptz not null default now(),
  unique (user_id, contest_id, alert_type)
);

create index if not exists idx_push_alert_log_user
  on public.push_alert_log (user_id);

create index if not exists idx_push_alert_log_sent
  on public.push_alert_log (sent_at desc);

alter table public.push_alert_log enable row level security;

-- Authenticated users can read their own delivery history (optional UI later).
-- Inserts/updates are service_role only (Edge Function).
drop policy if exists "Users read own push alert log" on public.push_alert_log;
create policy "Users read own push alert log"
  on public.push_alert_log for select
  using (auth.uid() = user_id);

grant select on public.push_alert_log to authenticated;
grant all on public.push_alert_log to service_role;

comment on table public.push_alert_log is
  'Dedup log for Expo push alerts (new contest / ending tonight).';

-- ---------------------------------------------------------------------------
-- Seed default notification prefs for existing profiles (additive jsonb merge)
-- Does not overwrite keys already present under settings.notifications
-- ---------------------------------------------------------------------------
update public.profiles
set settings = jsonb_set(
  coalesce(settings, '{}'::jsonb),
  '{notifications}',
  coalesce(settings->'notifications', '{}'::jsonb) || jsonb_build_object(
    'enabled', coalesce((settings->'notifications'->>'enabled')::boolean, true),
    'newContestsCA', coalesce((settings->'notifications'->>'newContestsCA')::boolean, true),
    'newContestsUS', coalesce((settings->'notifications'->>'newContestsUS')::boolean, false),
    'endingTonight', coalesce((settings->'notifications'->>'endingTonight')::boolean, true)
  ),
  true
)
where settings->'notifications' is null
   or settings->'notifications' = '{}'::jsonb
   or settings->'notifications'->>'enabled' is null;

-- ---------------------------------------------------------------------------
-- Account deletion: also wipe push rows (redefines RPC — same signature)
-- ---------------------------------------------------------------------------
create or replace function public.delete_own_account()
returns void
language plpgsql
security definer
set search_path = public, tracking, giveaways, auth
as $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'Not authenticated';
  end if;

  delete from public.push_alert_log where user_id = uid;
  delete from public.push_tokens where user_id = uid;
  delete from tracking.contest_entries where user_id = uid;
  delete from tracking.transactions where user_id = uid;
  delete from giveaways.user_wins where user_id = uid;
  delete from giveaways.referral_pool where referrer_id = uid;
  delete from public.profiles where id = uid;

  -- Legacy public tables if present on older projects
  begin
    delete from public.applied_contests where user_id = uid;
  exception when undefined_table then null;
  end;
  begin
    delete from public.transactions where user_id = uid;
  exception when undefined_table then null;
  end;
  begin
    delete from public.user_wins where user_id = uid;
  exception when undefined_table then null;
  end;
  begin
    delete from public.referral_pool where referrer_id = uid;
  exception when undefined_table then null;
  end;

  delete from auth.users where id = uid;
end;
$$;

revoke all on function public.delete_own_account() from public;
grant execute on function public.delete_own_account() to authenticated;

comment on function public.delete_own_account() is
  'Deletes the calling user account and associated personal rows (incl. push tokens/alerts).';

